CREATE OR REPLACE FUNCTION public.enforce_invite_only_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE invite_id uuid; BEGIN invite_id := NULLIF(new.raw_user_meta_data ->> 'invite_id', '')::uuid; IF invite_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.workspace_invites wi WHERE wi.id = invite_id AND wi.status = 'pending' AND wi.expires_at > now() AND wi.auth_mode = 'register' AND lower(wi.email) = lower(new.email)) THEN RAISE EXCEPTION 'Account creation requires a valid invitation'; END IF; RETURN new; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Account creation requires a valid invitation'; END; $$;